# Windows Desktop Application Testing Script
# Comprehensive testing for Windows applications

# Configuration
$AppName = "MyDesktopApp"
$AppVersion = "1.0.0"
$InstallPath = "C:\Program Files\$AppName"
$LogPath = "C:\Logs\$AppName-Test-$(Get-Date -Format 'yyyyMMdd_HHmmss').log"

# Start logging
Start-Transcript -Path $LogPath -Force

Write-Host "=== WINDOWS DESKTOP APPLICATION TESTING ===" -ForegroundColor Cyan
Write-Host "Application: $AppName v$AppVersion"
Write-Host "Start Time: $(Get-Date)"
Write-Host ""

# Function to write test result
function Write-TestResult {
    param(
        [string]$TestName,
        [bool]$Passed,
        [string]$Details = ""
    )

    $color = if ($Passed) { "Green" } else { "Red" }
    $status = if ($Passed) { "PASS" } else { "FAIL" }

    Write-Host "[$status] $TestName" -ForegroundColor $color
    if ($Details) {
        Write-Host "  Details: $Details" -ForegroundColor Gray
    }
}

# 1. System Requirements Check
Write-Host "\n1. SYSTEM REQUIREMENTS CHECK" -ForegroundColor Yellow

# Check Windows version
$WindowsVersion = [System.Environment]::OSVersion.Version
$WindowsBuild = (Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion").CurrentBuildNumber
Write-Host "Windows Version: $WindowsVersion"
Write-Host "Windows Build: $WindowsBuild"

$minWindowsVersion = "10.0.18362"  # Windows 10 1903
$versionCheck = [System.Version]$WindowsVersion -ge [System.Version]$minWindowsVersion
Write-TestResult -TestName "Windows Version Check" -Passed $versionCheck -Details "Minimum: $minWindowsVersion, Current: $WindowsVersion"

# Check available RAM
$ramGB = (Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1GB
$ramCheck = $ramGB -ge 4  # Minimum 4GB
Write-TestResult -TestName "RAM Check" -Passed $ramCheck -Details "Available: $([math]::Round($ramGB, 2))GB, Minimum: 4GB"

# Check disk space
$disk = Get-PSDrive C
$freeSpaceGB = $disk.Free / 1GB
$diskCheck = $freeSpaceGB -ge 10  # Minimum 10GB free
Write-TestResult -TestName "Disk Space Check" -Passed $diskCheck -Details "Free: $([math]::Round($freeSpaceGB, 2))GB, Minimum: 10GB"

# Check .NET Framework
$dotNetVersions = Get-ChildItem "HKLM:\SOFTWARE\Microsoft\NET Framework Setup\NDP" -Recurse | Get-ItemProperty -Name Version -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^(?!S)\p{L}'} | Select-Object -ExpandProperty Version
$dotNetCheck = $dotNetVersions -contains "4.8"  # Check for .NET 4.8
Write-TestResult -TestName ".NET Framework Check" -Passed $dotNetCheck -Details "Available versions: $($dotNetVersions -join ', ')"

# 2. Installation Testing
Write-Host "\n2. INSTALLATION TESTING" -ForegroundColor Yellow

# Check if application is already installed
$uninstallKey = Get-ChildItem "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall" | 
    Get-ItemProperty | Where-Object { $_.DisplayName -like "*$AppName*" }

if ($uninstallKey) {
    Write-Host "Application is already installed. Testing uninstallation first..."

    # Test uninstallation
    $uninstallString = $uninstallKey.UninstallString
    if ($uninstallString) {
        try {
            Start-Process -FilePath "msiexec.exe" -ArgumentList "/x $($uninstallKey.PSChildName) /quiet /norestart" -Wait -NoNewWindow
            Write-TestResult -TestName "Uninstallation" -Passed $true -Details "Successfully uninstalled previous version"
            Start-Sleep -Seconds 5
        } catch {
            Write-TestResult -TestName "Uninstallation" -Passed $false -Details "Failed to uninstall: $_"
        }
    }
}

# Test installation
$installerPath = "C:\Installers\$AppName-Setup.msi"
if (Test-Path $installerPath) {
    Write-Host "Installing application from: $installerPath"

    try {
        # Install with logging
        $installLog = "C:\Logs\$AppName-Install-$(Get-Date -Format 'yyyyMMdd_HHmmss').log"
        $installArgs = "/i `"$installerPath`" /quiet /norestart /l*v `"$installLog`""

        $process = Start-Process -FilePath "msiexec.exe" -ArgumentList $installArgs -Wait -PassThru -NoNewWindow

        if ($process.ExitCode -eq 0) {
            Write-TestResult -TestName "Installation" -Passed $true -Details "Exit code: $($process.ExitCode)"

            # Verify installation
            if (Test-Path $InstallPath) {
                Write-TestResult -TestName "Installation Verification" -Passed $true -Details "Files installed to: $InstallPath"
            } else {
                Write-TestResult -TestName "Installation Verification" -Passed $false -Details "Installation path not found: $InstallPath"
            }
        } else {
            Write-TestResult -TestName "Installation" -Passed $false -Details "Exit code: $($process.ExitCode)"
        }
    } catch {
        Write-TestResult -TestName "Installation" -Passed $false -Details "Exception: $_"
    }
} else {
    Write-Host "Installer not found: $installerPath" -ForegroundColor Yellow
}

# 3. Registry and Configuration Testing
Write-Host "\n3. REGISTRY AND CONFIGURATION TESTING" -ForegroundColor Yellow

# Check registry entries
$registryTests = @(
    @{Path = "HKLM:\SOFTWARE\$AppName"; Description = "Application registry key"; ShouldExist = $true},
    @{Path = "HKCU:\SOFTWARE\$AppName"; Description = "User configuration key"; ShouldExist = $true},
    @{Path = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\$AppName"; Description = "Uninstall information"; ShouldExist = $true}
)

foreach ($test in $registryTests) {
    $exists = Test-Path $test.Path
    $passed = $exists -eq $test.ShouldExist
    Write-TestResult -TestName $test.Description -Passed $passed -Details "Path: $($test.Path), Exists: $exists"
}

# Check environment variables
$envVarName = "${AppName}_PATH"
$envVarValue = [Environment]::GetEnvironmentVariable($envVarName, "Machine")
$envVarCheck = $envVarValue -eq $InstallPath
Write-TestResult -TestName "Environment Variable" -Passed $envVarCheck -Details "$envVarName = $envVarValue"

# 4. Application Launch Testing
Write-Host "\n4. APPLICATION LAUNCH TESTING" -ForegroundColor Yellow

# Find application executable
$exePaths = @(
    "$InstallPath\$AppName.exe",
    "C:\ProgramData\Microsoft\Windows\Start Menu\Programs\$AppName\$AppName.exe",
    [Environment]::GetFolderPath("Desktop") + "\$AppName.lnk"
)

$appExe = $null
foreach ($path in $exePaths) {
    if (Test-Path $path) {
        $appExe = $path
        Write-Host "Found application at: $appExe"
        break
    }
}

if ($appExe) {
    # Test application launch
    Write-Host "Testing application launch..."

    try {
        # Measure startup time
        $startTime = Get-Date
        $process = Start-Process -FilePath $appExe -PassThru -WindowStyle Minimized

        # Wait for process to initialize
        Start-Sleep -Seconds 5

        $endTime = Get-Date
        $startupTime = ($endTime - $startTime).TotalSeconds

        # Check if process is running
        if (-not $process.HasExited) {
            Write-TestResult -TestName "Application Launch" -Passed $true -Details "PID: $($process.Id), Startup time: ${startupTime}s"

            # Get process information
            $procInfo = Get-Process -Id $process.Id
            $memoryMB = $procInfo.WorkingSet64 / 1MB
            Write-Host "  Process memory usage: $([math]::Round($memoryMB, 2))MB"

            # Close application
            $process.CloseMainWindow() | Out-Null
            Start-Sleep -Seconds 2
            if (-not $process.HasExited) {
                $process.Kill()
                Write-Host "  Application terminated"
            }
        } else {
            Write-TestResult -TestName "Application Launch" -Passed $false -Details "Process exited immediately. Exit code: $($process.ExitCode)"
        }
    } catch {
        Write-TestResult -TestName "Application Launch" -Passed $false -Details "Exception: $_"
    }
} else {
    Write-TestResult -TestName "Application Launch" -Passed $false -Details "Executable not found"
}

# 5. File System and Permission Testing
Write-Host "\n5. FILE SYSTEM AND PERMISSION TESTING" -ForegroundColor Yellow

# Test file creation in application directory
$testFile = "$InstallPath\test_permission.txt"
try {
    "Test content" | Out-File -FilePath $testFile -Force
    $fileCreated = Test-Path $testFile
    Write-TestResult -TestName "File Creation Permission" -Passed $fileCreated -Details "Created: $testFile"

    if ($fileCreated) {
        Remove-Item $testFile -Force
    }
} catch {
    Write-TestResult -TestName "File Creation Permission" -Passed $false -Details "Exception: $_"
}

# Test access to common directories
$directoryTests = @(
    @{Path = [Environment]::GetFolderPath("MyDocuments"); Description = "My Documents access"},
    @{Path = [Environment]::GetFolderPath("Desktop"); Description = "Desktop access"},
    @{Path = "C:\Windows\Temp"; Description = "Temp directory access"}
)

foreach ($test in $directoryTests) {
    $testFile = Join-Path $test.Path "${AppName}_test.txt"
    try {
        "Test" | Out-File -FilePath $testFile -Force -ErrorAction Stop
        $passed = Test-Path $testFile
        Write-TestResult -TestName $test.Description -Passed $passed -Details "Path: $test.Path"

        if ($passed) {
            Remove-Item $testFile -Force -ErrorAction SilentlyContinue
        }
    } catch {
        Write-TestResult -TestName $test.Description -Passed $false -Details "Access denied to: $test.Path"
    }
}

# 6. Windows Service Testing (if applicable)
Write-Host "\n6. WINDOWS SERVICE TESTING" -ForegroundColor Yellow

$serviceName = "${AppName}Service"
$service = Get-Service -Name $serviceName -ErrorAction SilentlyContinue

if ($service) {
    Write-Host "Found service: $serviceName"

    # Test service state
    $serviceState = $service.Status
    Write-TestResult -TestName "Service Existence" -Passed $true -Details "Status: $serviceState"

    # Test service start/stop
    try {
        if ($service.Status -eq 'Running') {
            Stop-Service -Name $serviceName -Force -ErrorAction Stop
            Start-Sleep -Seconds 3
            $service.Refresh()
            Write-TestResult -TestName "Service Stop" -Passed ($service.Status -eq 'Stopped') -Details "Stopped service"

            Start-Service -Name $serviceName -ErrorAction Stop
            Start-Sleep -Seconds 3
            $service.Refresh()
            Write-TestResult -TestName "Service Start" -Passed ($service.Status -eq 'Running') -Details "Started service"
        } else {
            Start-Service -Name $serviceName -ErrorAction Stop
            Start-Sleep -Seconds 3
            $service.Refresh()
            Write-TestResult -TestName "Service Start" -Passed ($service.Status -eq 'Running') -Details "Started service"

            Stop-Service -Name $serviceName -Force -ErrorAction Stop
            Start-Sleep -Seconds 3
            $service.Refresh()
            Write-TestResult -TestName "Service Stop" -Passed ($service.Status -eq 'Stopped') -Details "Stopped service"
        }
    } catch {
        Write-TestResult -TestName "Service Control" -Passed $false -Details "Exception: $_"
    }
} else {
    Write-Host "Service $serviceName not found (may not be applicable)" -ForegroundColor Gray
}

# 7. Event Log Testing
Write-Host "\n7. EVENT LOG TESTING" -ForegroundColor Yellow

# Check application event log entries
$logName = "Application"
$source = $AppName

# Try to create an event source if it doesn't exist
if (-not [System.Diagnostics.EventLog]::SourceExists($source)) {
    try {
        New-EventLog -LogName $logName -Source $source -ErrorAction SilentlyContinue
    } catch {
        Write-Host "Note: Could not create event log source (may require admin rights)" -ForegroundColor Yellow
    }
}

# Write test event
try {
    Write-EventLog -LogName $logName -Source $source -EventId 1001 -EntryType Information -Message "Test event from $AppName testing script" -Category 0
    Write-TestResult -TestName "Event Log Writing" -Passed $true -Details "Wrote test event to $logName log"
} catch {
    Write-TestResult -TestName "Event Log Writing" -Passed $false -Details "Exception: $_"
}

# 8. Performance Testing
Write-Host "\n8. PERFORMANCE TESTING" -ForegroundColor Yellow

# Monitor application resource usage
if ($appExe) {
    Write-Host "Starting performance monitoring..."

    $perfLog = "C:\Logs\$AppName-Perf-$(Get-Date -Format 'yyyyMMdd_HHmmss').csv"
    "Timestamp,CPU(%),Memory(MB),Handles,Threads" | Out-File $perfLog -Force

    $process = Start-Process -FilePath $appExe -PassThru -WindowStyle Minimized

    # Monitor for 30 seconds
    $monitorTime = 30
    for ($i = 1; $i -le $monitorTime; $i++) {
        try {
            $procInfo = Get-Process -Id $process.Id -ErrorAction Stop
            $cpu = $procInfo.CPU
            $memoryMB = [math]::Round($procInfo.WorkingSet64 / 1MB, 2)
            $handles = $procInfo.HandleCount
            $threads = $procInfo.Threads.Count
            $timestamp = Get-Date -Format "HH:mm:ss"

            "$timestamp,$cpu,$memoryMB,$handles,$threads" | Out-File $perfLog -Append

            Write-Host "  [$timestamp] CPU: ${cpu}%, Memory: ${memoryMB}MB" -ForegroundColor Gray

            if ($i -lt $monitorTime) {
                Start-Sleep -Seconds 1
            }
        } catch {
            Write-Host "  Process monitoring error: $_" -ForegroundColor Yellow
            break
        }
    }

    # Close application
    $process.CloseMainWindow() | Out-Null
    Start-Sleep -Seconds 2
    if (-not $process.HasExited) {
        $process.Kill()
    }

    Write-TestResult -TestName "Performance Monitoring" -Passed $true -Details "Log saved to: $perfLog"
}

# 9. Cleanup Testing
Write-Host "\n9. CLEANUP AND UNINSTALLATION TESTING" -ForegroundColor Yellow

# Test uninstallation
$uninstallKey = Get-ChildItem "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall" | 
    Get-ItemProperty | Where-Object { $_.DisplayName -like "*$AppName*" } | Select-Object -First 1

if ($uninstallKey) {
    $uninstallString = $uninstallKey.UninstallString
    Write-Host "Uninstall string: $uninstallString"

    # Ask for confirmation before uninstalling
    $response = Read-Host "\nDo you want to test uninstallation? (y/n)"
    if ($response -eq 'y') {
        try {
            if ($uninstallString -match 'msiexec') {
                # MSI uninstallation
                $productCode = $uninstallKey.PSChildName
                $process = Start-Process -FilePath "msiexec.exe" -ArgumentList "/x $productCode /quiet /norestart" -Wait -PassThru -NoNewWindow

                if ($process.ExitCode -eq 0) {
                    Write-TestResult -TestName "Uninstallation" -Passed $true -Details "Successfully uninstalled. Exit code: $($process.ExitCode)"

                    # Verify uninstallation
                    if (-not (Test-Path $InstallPath)) {
                        Write-TestResult -TestName "Uninstallation Verification" -Passed $true -Details "Application directory removed"
                    } else {
                        Write-TestResult -TestName "Uninstallation Verification" -Passed $false -Details "Application directory still exists: $InstallPath"
                    }
                } else {
                    Write-TestResult -TestName "Uninstallation" -Passed $false -Details "Exit code: $($process.ExitCode)"
                }
            } else {
                # Other installer type
                Write-Host "Non-MSI uninstaller detected. Manual testing required." -ForegroundColor Yellow
            }
        } catch {
            Write-TestResult -TestName "Uninstallation" -Passed $false -Details "Exception: $_"
        }
    } else {
        Write-Host "Skipping uninstallation test" -ForegroundColor Yellow
    }
}

# 10. Generate Test Report
Write-Host "\n10. TEST REPORT GENERATION" -ForegroundColor Yellow

$reportPath = "C:\Logs\$AppName-Test-Report-$(Get-Date -Format 'yyyyMMdd_HHmmss').html"

# Create HTML report
$html = @"
<!DOCTYPE html>
<html>
<head>
    <title>Windows Application Test Report - $AppName</title>
    <style>
        body { font-family: Arial, sans-serif; margin: 20px; }
        h1 { color: #333; }
        .test-result { margin: 10px 0; padding: 10px; border-left: 5px solid; }
        .pass { border-color: green; background-color: #e8f5e9; }
        .fail { border-color: red; background-color: #ffebee; }
        .summary { background: #f5f5f5; padding: 20px; border-radius: 5px; }
    </style>
</head>
<body>
    <h1>Windows Application Test Report</h1>
    <p><strong>Application:</strong> $AppName v$AppVersion</p>
    <p><strong>Test Date:</strong> $(Get-Date)</p>
    <p><strong>System:</strong> Windows $WindowsVersion (Build $WindowsBuild)</p>

    <div class="summary">
        <h2>Test Summary</h2>
        <p>Tests completed. See details below.</p>
    </div>

    <h2>Detailed Results</h2>
    <p>Refer to log file for complete details: $LogPath</p>
</body>
</html>
"@

$html | Out-File $reportPath -Force
Write-TestResult -TestName "Report Generation" -Passed $true -Details "Report saved to: $reportPath"

# Summary
Write-Host "\n"
Write-Host "=" * 60 -ForegroundColor Cyan
Write-Host "TESTING COMPLETE" -ForegroundColor Cyan
Write-Host "=" * 60 -ForegroundColor Cyan
Write-Host "Log file: $LogPath"
Write-Host "Report: $reportPath"
Write-Host "End Time: $(Get-Date)"

# Stop logging
Stop-Transcript

