// Simulating the beautiful chaos of actual office collaboration

class OfficeDaySimulator {
    constructor() {
        this.departments = ['Sales', 'Engineering', 'Marketing', 'Support', 'HR'];
        this.meetingRooms = ['Boardroom', 'Conference A', 'Conference B', 'Huddle 1', 'Huddle 2'];
        this.events = [];
        this.conflicts = [];
    }

    // Simulate how real people book meetings
    simulateRealisticBooking(user, room, startTime, duration) {
        const event = {
            user,
            room,
            startTime,
            duration,
            status: 'attempting',
            quirks: []
        };

        // Real human behaviors
        const behaviors = [
            () => {
                // User checks multiple times
                event.quirks.push('checked calendar 3 times before booking');
            },
            () => {
                // User books, then immediately modifies
                event.quirks.push('changed duration after booking');
            },
            () => {
                // User books 'just in case'
                event.quirks.push('blocked room as placeholder');
            },
            () => {
                // User forgets and double-books
                event.quirks.push('forgot about existing meeting');
            }
        ];

        // Add random human quirks
        behaviors.forEach(behavior => {
            if (Math.random() > 0.7) behavior();
        });

        // Check for conflicts (like real systems sometimes miss)
        const conflict = this.findConflict(room, startTime, duration);
        if (conflict) {
            event.status = 'conflict';
            event.conflictWith = conflict.user;
            this.conflicts.push({
                room,
                time: startTime,
                users: [user, conflict.user],
                resolution: this.simulateConflictResolution(user, conflict.user)
            });
        } else {
            event.status = 'booked';
            this.events.push(event);
        }

        return event;
    }

    findConflict(room, startTime, duration) {
        // Simulating race conditions: sometimes conflicts aren't detected immediately
        const conflictDelay = Math.random() > 0.8; // 20% chance of delayed conflict detection

        if (conflictDelay) {
            console.log(`⚠️  System lag: conflict detection delayed for ${room}`);
            return null; // Temporary false negative
        }

        return this.events.find(event => 
            event.room === room &&
            event.status === 'booked' &&
            this.timesOverlap(startTime, duration, event.startTime, event.duration)
        );
    }

    timesOverlap(start1, dur1, start2, dur2) {
        const end1 = start1 + dur1;
        const end2 = start2 + dur2;
        return start1 < end2 && start2 < end1;
    }

    simulateConflictResolution(user1, user2) {
        const resolutions = [
            `${user1} graciously reschedules`, // Collaborative
            `${user2} insists on keeping the room`, // Assertive
            `Both show up and have awkward standoff`, // No resolution
            `They find an empty conference room together`, // Creative solution
            `Manager intervenes and gives room to ${Math.random() > 0.5 ? user1 : user2}` // Escalation
        ];

        return resolutions[Math.floor(Math.random() * resolutions.length)];
    }

    simulateMorningRush() {
        console.log('🌅 SIMULATING OFFICE MORNING RUSH (8:30-9:30 AM)');
        console.log('='.repeat(50));

        const users = [
            'Alex (Sales, impatient)',
            'Jamila (Engineering, methodical)',
            'Marcus (Marketing, last-minute)',
            'Sofia (Support, always early)',
            'David (HR, conflict-averse)'
        ];

        // Simulate 30 minutes of booking activity
        const bookings = [];
        for (let i = 0; i < 20; i++) {
            const user = users[Math.floor(Math.random() * users.length)];
            const room = this.meetingRooms[Math.floor(Math.random() * this.meetingRooms.length)];
            const startTime = 8.5 + Math.random() * 1; // Between 8:30 and 9:30
            const duration = 0.5 + Math.random() * 1.5; // 30 min to 2 hours

            const booking = this.simulateRealisticBooking(user, room, startTime, duration);
            bookings.push(booking);

            const timeStr = this.formatTime(startTime);
            const durationStr = this.formatDuration(duration);

            if (booking.status === 'booked') {
                console.log(`✅ ${timeStr}: ${user} booked ${room} for ${durationStr}`);
                if (booking.quirks.length > 0) {
                    console.log(`   ↳ ${booking.quirks.join(', ')}`);
                }
            } else {
                console.log(`❌ ${timeStr}: ${user} conflicted with ${booking.conflictWith} for ${room}`);
            }
        }

        console.log('\n📊 MORNING RUSH RESULTS:');
        console.log(`Total booking attempts: ${bookings.length}`);
        console.log(`Successful bookings: ${bookings.filter(b => b.status === 'booked').length}`);
        console.log(`Conflicts detected: ${this.conflicts.length}`);

        if (this.conflicts.length > 0) {
            console.log('\n⚡ CONFLICT RESOLUTIONS:');
            this.conflicts.forEach((conflict, i) => {
                console.log(`${i+1}. ${conflict.room} at ${this.formatTime(conflict.time)}:`);
                console.log(`   ${conflict.resolution}`);
            });
        }
    }

    formatTime(hours) {
        const h = Math.floor(hours);
        const m = Math.floor((hours - h) * 60);
        return `${h}:${m.toString().padStart(2, '0')}`;
    }

    formatDuration(hours) {
        const h = Math.floor(hours);
        const m = Math.floor((hours - h) * 60);
        return `${h}h ${m}m`;
    }
}

